DO $ddl$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.release_stock_reservation(uuid,boolean,text,text)'::regprocedure) INTO d; d:=replace(d,'NOT public.has_capability(uid,''stock.reservation.cancel'')',E'NOT (public.has_capability(uid,''stock.reservation.cancel'') OR (public.colab_restrita() AND public.has_capability(uid,''kit.manage'') AND NOT _cancelar AND EXISTS(SELECT 1 FROM public.kit_cycles c JOIN public.kit_compositions co ON co.cycle_id=c.id JOIN public.kit_composition_items i ON i.composition_id=co.id WHERE public.colab_cycle_ok(c.id) AND c.status=''conferida'' AND co.frozen_at IS NOT NULL AND i.reservation_id=_reservation_id AND _idempotency_key=''maleta-exp-rel:''||i.id::text)))'); EXECUTE d; END $ddl$;